import { igesSection,handleIgesClick } from './iges.js';
import { icon,escapeHTML as esc } from './ui.js';
import { REFORM_VERSION,REFORM_SOURCES,SCENARIOS,WEIGHT_GROUPS,REFORM_MODULES,compareThresholds,compareModule } from './reform-data.js';
const fmt=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n);
const gradeName=n=>n===0?'Kein Pflegegrad':`Pflegegrad ${n}`;
const bandLabel=([a,b])=>a===b?fmt(a):`${fmt(a)}–${fmt(b)}`;
const groupFor=module=>WEIGHT_GROUPS.find(g=>g.modules.includes(module));
function pointScale(id,points,highlight){
  const rule=SCENARIOS[id],grade=compareThresholds(points)[id];
  return `<div class="threshold-scale ${highlight===id?'is-emphasized':''}" data-scale="${id}"><div class="scale-title"><strong>${rule.label}</strong><span>${gradeName(grade)}</span></div><div class="scale-plot"><div class="grade-segments" aria-hidden="true">${rule.thresholds.map((low,i)=>`<span class="grade-zone grade-zone-${i} ${i===grade?'is-current-grade':''}" style="width:${(rule.thresholds[i+1]??100)-low}%"><span>${i===0?'–':i}</span></span>`).join('')}</div><span class="point-cursor" style="left:${points}%" aria-hidden="true"></span><div class="scale-ticks" aria-hidden="true"><span class="scale-zero">0</span>${rule.thresholds.slice(1).map((n,i)=>`<span style="left:${n}%">${fmt(n)}</span>`).join('')}<span class="scale-hundred">100</span></div></div><p class="sr-only">${rule.thresholds.map((n,i)=>`${gradeName(i)}: ${fmt(n)} bis ${i<5?'unter ':''}${fmt(rule.thresholds[i+1]??100)} Punkte`).join('; ')}.</p></div>`;
}
export function thresholdVisual(state){
  const result=compareThresholds(state.points);
  return `<div class="threshold-scales">${pointScale('current',state.points,state.highlight)}${pointScale('draft',state.points,state.highlight)}</div><p class="scale-key">Die Zahlen in den Farbbereichen stehen für die Pflegegrade. „–“ bedeutet kein Pflegegrad.</p><div class="threshold-result"><p class="comparison-overline">Bei ${fmt(state.points)} Gesamtpunkten</p><div class="comparison-pair"><div class="comparison-value tone-ice"><span>Heute</span><strong>${gradeName(result.current)}</strong></div><span class="comparison-arrow" aria-hidden="true">${icon('arrow')}</span><div class="comparison-value tone-cream"><span>Geplant · Entwurf</span><strong>${gradeName(result.draft)}</strong></div></div></div>`;
}
function rawTable(module){
  const current=SCENARIOS.current.tables[module].bands,draft=SCENARIOS.draft.tables[module].bands;
  return `<details class="reform-table-details"><summary>Alle Umrechnungsbereiche ansehen</summary><div class="table-wrap"><table><caption>Modul ${module}: Einzelpunktsummen und gewichtete Punkte</caption><thead><tr><th scope="col">Heute: Einzelpunkte</th><th scope="col">Entwurf: Einzelpunkte</th><th scope="col">Gewichtete Punkte</th></tr></thead><tbody>${current.map((b,i)=>`<tr><td>${bandLabel(b)}</td><td>${bandLabel(draft[i])}</td><td>${fmt(b[2])}</td></tr>`).join('')}</tbody></table></div></details>`;
}
export function moduleVisual(state){
  const r=compareModule(state.module,state.raw[state.module]),weight=groupFor(state.module).weight;
  return `<div class="module-comparison-result"><div class="module-value-pair">${[['current','Heute · geltend','ice'],['draft','2027 · Entwurf','cream']].map(([key,label,tone])=>`<div class="module-value tone-${tone}"><p>${label}</p><strong>${fmt(r[key])}</strong><span>gewichtete Punkte</span><div class="module-weight-track" aria-hidden="true"><span style="width:${r[key]/weight*100}%"></span></div></div>`).join('')}</div><p class="module-delta ${r.difference===0?'unchanged':''}">${icon(r.difference===0?'check':'compare')}${r.difference===0?'Bei dieser Einzelpunktsumme unverändert':`${fmt(Math.abs(r.difference))} gewichtete Punkte weniger im Entwurf`}</p></div><p class="module-conversion-note">${state.module===2||state.module===3?'Aus Modul 2 und 3 wird nur der höhere gewichtete Wert übernommen.':`Dieses Modul trägt höchstens ${weight} Punkte zum Gesamtwert bei.`}</p>`;
}
export function modulePanel(state){
  const m=REFORM_MODULES.find(m=>m.id===state.module),max=SCENARIOS.current.tables[state.module].maxRaw;
  return `<div class="raw-control"><label for="reform-raw">Einzelpunkte in „${m.label}“</label><div class="range-input-row"><input type="range" id="reform-raw" min="0" max="${max}" step="1" value="${state.raw[state.module]}" aria-describedby="raw-error"><label class="number-field"><span class="sr-only">Einzelpunkte direkt eingeben</span><input id="reform-raw-number" type="number" min="0" max="${max}" step="1" inputmode="numeric" value="${state.raw[state.module]}" aria-describedby="raw-error"></label></div><div class="range-limits" aria-hidden="true"><span>0</span><span>${max} Einzelpunkte</span></div><p class="form-error" id="raw-error" role="alert"></p></div><div id="module-visual">${moduleVisual(state)}</div>${rawTable(state.module)}`;
}
export function weightDetail(module){
  const m=REFORM_MODULES.find(m=>m.id===module),g=groupFor(module);
  return `<div class="weight-detail tone-${g.tone}"><div class="weight-big">${g.weight}<span>%</span></div><div><p class="comparison-overline">${g.id==='23'?'Gemeinsamer Anteil der Module 2 & 3':`Modul ${module}`}</p><h3>${m.title}</h3><p>${m.description}</p>${g.id==='23'?'<p class="combined-weight-rule"><strong>Es zählt nur der höhere gewichtete Wert.</strong> Die beiden Module werden nicht addiert.</p>':''}</div></div>`;
}
function weightChart(state){
  return `<div class="weight-stack" role="group" aria-label="Die fünf Gewichtsanteile ergeben 100 Prozent">${WEIGHT_GROUPS.map(g=>`<button class="weight-segment tone-${g.tone}" data-weight-group="${g.id}" aria-label="${g.label}: ${g.weight} Prozent${g.id==='23'?'; Module 2 und 3 gemeinsam':''}" aria-pressed="${g.modules.includes(state.weightModule)}" style="flex-basis:${g.weight}%"><strong>${g.weight}<span>%</span></strong></button>`).join('')}</div><div class="weight-module-list" role="group" aria-label="Modul erklären">${REFORM_MODULES.map(m=>`<button data-weight-module="${m.id}" aria-pressed="${m.id===state.weightModule}"><span class="weight-dot tone-${groupFor(m.id).tone}" aria-hidden="true">${m.id}</span><span>${m.label}</span>${[2,3].includes(m.id)?'<small>gemeinsam</small>':`<strong>${groupFor(m.id).weight} %</strong>`}</button>`).join('')}</div><div id="weight-detail">${weightDetail(state.weightModule)}</div>`;
}
export function reformComparisonPage(state){
  return `<div class="page reform-comparison-page route-enter"><header class="page-header reform-comparison-header"><p class="reform-status">${icon('info')} Gesetzentwurf · noch nicht beschlossen</p><h1>Pflegereform 2027<span> – Was ändert sich?</span></h1><p class="lead">Grenzen, Modulpunkte und Gewichtung im direkten Vergleich.</p><p class="reform-checked">Geprüft am 12.11.2026 · Der Selbstcheck rechnet weiterhin nach geltendem Recht.</p></header><nav class="reform-section-nav" aria-label="Zum Vergleich springen"><button data-reform-jump="reform-gewichtung">Punktesystem</button><button data-reform-jump="reform-grenzen">Punktegrenzen</button><button data-reform-jump="reform-module">Umrechnung</button><button data-reform-jump="reform-auswirkungen">Auswirkungen</button></nav>
  <section class="reform-panel weights-panel" id="reform-gewichtung" aria-labelledby="weight-heading"><div class="reform-panel-heading"><div><p class="eyebrow">01 / Das Punktesystem</p><h2 id="weight-heading" tabindex="-1">Wie wird ein Pflegegrad berechnet?</h2></div><span class="unchanged-badge">${icon('check')} Gewichtung bleibt im Entwurf gleich</span></div><p class="points-intro">Bei der Begutachtung wird geprüft, wie selbstständig eine Person ihren Alltag bewältigen kann. Verschiedene Lebensbereiche werden bewertet. Je mehr Unterstützung nötig ist, desto mehr Punkte werden vergeben.</p>${weightChart(state)}<p class="weight-caption">Module 2 und 3 teilen sich 15 %. Ihr höherer gewichteter Wert zählt einmal.</p><ol class="points-journey" aria-label="Von der Einschätzung zum Pflegegrad"><li><span class="journey-step">1 / Alltag einschätzen</span><h3>Wie viel Hilfe ist nötig?</h3><div class="journey-number">0 <span>–</span> 3</div><p>Einzelpunkte je Mobilitätskriterium – abhängig von der benötigten Hilfe.</p><details class="journey-help"><summary>Die vier Antworten ansehen</summary><p>Beispiel: ein Mobilitätskriterium</p><ul class="journey-options"><li><span>Selbstständig</span><strong>0</strong></li><li><span>Überwiegend selbstständig</span><strong>1</strong></li><li><span>Überwiegend unselbstständig</span><strong>2</strong></li><li><span>Unselbstständig</span><strong>3</strong></li></ul><small>Einzelpunkte. Andere Kriterien haben teilweise andere Skalen.</small></details></li><li><span class="journey-step">2 / Punkte umrechnen</span><h3>Feste Tabellen gewichten.</h3><div class="journey-number">5 <span>→</span> 5</div><p>5 Einzelpunkte im Modul Mobilität ergeben 5 gewichtete Punkte.</p></li><li><span class="journey-step">3 / Pflegegrad bestimmen</span><h3>Gewichtete Punkte addieren.</h3><div class="journey-number">35 <span>→</span> PG 2</div><p>35 Gesamtpunkte entsprechen Pflegegrad 2.</p></li></ol><p class="journey-footnote">Beispiele nach geltendem Recht. Schritt 2 und 3 zeigen unabhängige Beispiele; aus den Mobilitätspunkten allein entsteht kein Pflegegrad.</p></section>
  <section class="reform-panel" id="reform-grenzen" aria-labelledby="threshold-heading"><div class="reform-panel-heading"><div><p class="eyebrow">02 / Der Einstieg in einen Pflegegrad</p><h2 id="threshold-heading" tabindex="-1">Wie viele Punkte braucht es?</h2></div><div class="reform-view-switch" role="group" aria-label="Regelstand hervorheben"><button data-reform-highlight="current" aria-pressed="${state.highlight==='current'}">2026 · geltend</button><button data-reform-highlight="draft" aria-pressed="${state.highlight==='draft'}">2027 · Entwurf</button></div></div>
  <div class="total-control"><label for="reform-points">Gesamtpunkte ausprobieren</label><div class="range-input-row"><input id="reform-points" type="range" min="0" max="100" step="0.01" value="${state.points}" aria-describedby="threshold-note points-error"><label class="number-field"><span class="sr-only">Gesamtpunkte direkt eingeben</span><input type="number" id="reform-points-number" min="0" max="100" step="0.01" inputmode="decimal" value="${state.points}" aria-describedby="threshold-note points-error"></label></div><p id="points-error" class="form-error" role="alert"></p></div><div id="threshold-visual">${thresholdVisual(state)}</div><p class="threshold-disclaimer" id="threshold-note"><strong>Nur ein Vergleich der Grenzwerte.</strong> Die Punkte werden hier nicht neu berechnet. Gleiche Antworten können im Entwurf andere Gesamtpunkte ergeben.</p><details class="reform-extra"><summary>Grenzen & Sonderfälle</summary><div class="details-body"><p>Für die Pflegegrade 1, 2 und 3 sieht der Entwurf ${SCENARIOS.draft.thresholds.slice(1,4).map(fmt).join(', ')} statt ${SCENARIOS.current.thresholds.slice(1,4).map(fmt).join(', ')} Punkte vor. Pflegegrad 4 bleibt ab 70, Pflegegrad 5 ab 90 Punkten.</p><p>Der Vergleich bezieht sich auf Erwachsene. Die gesetzliche besondere Bedarfskonstellation für Pflegegrad 5 unter 90 Punkten muss fachlich beurteilt werden und wird hier nicht automatisch berücksichtigt.</p><p>Der Regler zeigt eine hypothetische Punktzahl. Nicht jede Dezimalzahl muss durch eine tatsächliche Modulberechnung erreichbar sein.</p></div></details></section>
  <section class="reform-panel module-reform-panel" id="reform-module" aria-labelledby="module-heading"><div class="reform-panel-heading"><div><p class="eyebrow">03 / Von Einzelpunkten zum Gesamtwert</p><h2 id="module-heading" tabindex="-1">Was zählt ein Punkt?</h2></div><label class="module-select-label" for="reform-module-select">Modul auswählen<select id="reform-module-select">${REFORM_MODULES.map(m=>`<option value="${m.id}" ${m.id===state.module?'selected':''}>${m.id} · ${m.label}</option>`).join('')}</select></label></div><p class="reform-short-intro">Auch die Umrechnung soll sich ändern: in Mobilität, Selbstversorgung und Alltagsgestaltung.</p><div id="module-panel">${modulePanel(state)}</div></section>

  <section class="reform-takeaways" aria-label="Was die Reform bedeuten würde"><h2 class="takeaways-heading">Was bedeutet die Reform konkret?</h2><article class="tone-ice"><span class="icon-surface">${icon('compare')}</span><h2>Höhere Punktegrenzen</h2><p>Pflegegrad 1 bis 3 sollen später erreicht werden.</p><details><summary>Mehr erfahren</summary><div class="details-body"><p>Die Einstiegsschwellen sollen um 2,5, 3 und 2,5 Punkte steigen. Zusammen mit der veränderten Umrechnung kann dies die rechnerische Einstufung beeinflussen. Eine individuelle Prognose lässt sich daraus nicht ableiten.</p></div></details></article><article class="tone-lavender"><span class="icon-surface">${icon('layers')}</span><h2>Andere Punkteberechnung</h2><p>Einige Einzelpunktsummen würden weniger zählen.</p><details><summary>Mehr erfahren</summary><div class="details-body"><p>Verändert werden im Entwurf die Bereiche in Modul 1, 4 und 6. Modul 2, 3 und 5 sowie die maximalen gewichteten Punkte bleiben gleich. Einzelpunkte und gewichtete Punkte sind unterschiedliche Größen.</p></div></details></article><article class="tone-cream"><span class="icon-surface">${icon('shield')}</span><h2>Anträge & Bestandsschutz</h2><p>Ein anerkannter Pflegegrad soll nicht allein durch die neuen Regeln verloren gehen.</p><details><summary>Mehr erfahren</summary><div class="details-body"><p>Der geplante § 142b knüpft an das Recht bei Antragstellung an; bei Wiederholungsbegutachtungen soll der Begutachtungstag zählen. Bestehende Zuordnungen sollen bis zu einer Neubegutachtung und anschließenden Entscheidung fortgelten. Eine neue Einstufung soll den bisherigen Pflegegrad nicht allein wegen neuer Schwellen oder Umrechnungstabellen entziehen.</p><p>Das schützt den Pflegegrad, nicht automatisch alle einzelnen Leistungsbeträge. Die geplante Ausnahme von der regulären Entscheidungsfrist von Januar bis April 2027 gilt heute nicht. Für dringliche Fälle sieht der Entwurf Sonderregeln vor. Keine neue Widerspruchsfrist wird daraus abgeleitet.</p><p>Diese Übergangsregeln sind noch nicht verbindlich. Daraus ergibt sich keine Empfehlung für einen bestimmten Antragsstichtag.</p></div></details></article></section>
  ${igesSection(state.impactGrade??2)}
  <details class="reform-source-panel"><summary>Rechtsstand & Originalquellen</summary><div class="details-body"><p>Stand ${REFORM_VERSION.checkedAt}: Regierungsentwurf vom 02.11.2026, erste Lesung am 05.11.2026, an die Ausschüsse überwiesen. Eine Anhörung ist für den 25.11.2026 angekündigt. Das Hauptinkrafttreten am 01.01.2027 ist geplant, nicht beschlossen.</p><p>Die aktuelle SGB-XI-Gesamtfassung berücksichtigt ${REFORM_VERSION.currentLawVersion}. Die Vergleichsdaten sind getrennt vom Selbstcheck versioniert; es gibt keine automatische Umstellung auf Entwurfsrecht.</p><ul>${Object.values(REFORM_SOURCES).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul><p>Datenversion: ${REFORM_VERSION.id}</p></div></details><div class="reform-bottom-links"><a class="button primary" href="#/rechner">Selbstcheck nach geltendem Recht ${icon('arrow')}</a><a class="text-link" href="#/reform-details">Gesetzgebung, Übergang & geplante Budgets ${icon('arrow')}</a></div></div>`;
}
export function handleReformInput(event,state){
  const input=event.target,total=['reform-points','reform-points-number'].includes(input.id),raw=['reform-raw','reform-raw-number'].includes(input.id);if(!total&&!raw)return false;
  const n=Number(input.value),max=total?100:SCENARIOS.current.tables[state.module].maxRaw,error=document.getElementById(total?'points-error':'raw-error');
  if(input.value.trim()===''||!Number.isFinite(n)||n<0||n>max||(!total&&!Number.isInteger(n))||input.validity?.stepMismatch){error.textContent=total?'Bitte geben Sie 0 bis 100 Punkte mit höchstens zwei Nachkommastellen ein.':`Bitte geben Sie eine ganze Zahl von 0 bis ${max} ein.`;input.setAttribute('aria-invalid','true');return true;}
  error.textContent='';const ids=total?['reform-points','reform-points-number']:['reform-raw','reform-raw-number'];for(const id of ids){const el=document.getElementById(id);el.value=String(n);el.removeAttribute('aria-invalid');}
  if(total){state.points=n;document.getElementById('threshold-visual').innerHTML=thresholdVisual(state);const r=compareThresholds(n);document.getElementById('announcement').textContent=`${fmt(n)} Punkte: heute ${gradeName(r.current)}, im Entwurf ${gradeName(r.draft)}. Nur Grenzwerte verglichen.`;}else{state.raw[state.module]=n;document.getElementById('module-visual').innerHTML=moduleVisual(state);const r=compareModule(state.module,n);document.getElementById('announcement').textContent=`${n} Einzelpunkte: heute ${fmt(r.current)}, im Entwurf ${fmt(r.draft)} gewichtete Punkte.`;}return true;
}
export function handleReformChange(event,state){
  if(event.target.id!=='reform-module-select')return false;const module=Number(event.target.value);if(!REFORM_MODULES.some(m=>m.id===module))return true;state.module=module;document.getElementById('module-panel').innerHTML=modulePanel(state);document.getElementById('announcement').textContent=`Umrechnung für Modul ${module}: ${REFORM_MODULES[module-1].label}.`;return true;
}
export function handleReformClick(event,state){
  if(handleIgesClick(event,state))return true;
  const jump=event.target.closest('[data-reform-jump]');if(jump){const section=document.getElementById(jump.dataset.reformJump);section?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});section?.querySelector('h2').focus({preventScroll:true});return true;}
  const highlight=event.target.closest('[data-reform-highlight]');if(highlight){state.highlight=highlight.dataset.reformHighlight;document.querySelectorAll('[data-reform-highlight]').forEach(b=>b.setAttribute('aria-pressed',String(b===highlight)));document.getElementById('threshold-visual').innerHTML=thresholdVisual(state);return true;}
  const module=event.target.closest('[data-weight-module]'),group=event.target.closest('[data-weight-group]');if(module||group){state.weightModule=module?Number(module.dataset.weightModule):WEIGHT_GROUPS.find(g=>g.id===group.dataset.weightGroup).modules[0];document.querySelectorAll('[data-weight-module]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.weightModule)===state.weightModule)));document.querySelectorAll('[data-weight-group]').forEach(b=>b.setAttribute('aria-pressed',String(groupFor(state.weightModule).id===b.dataset.weightGroup)));document.getElementById('weight-detail').innerHTML=weightDetail(state.weightModule);const g=groupFor(state.weightModule);document.getElementById('announcement').textContent=`${REFORM_MODULES[state.weightModule-1].title}: ${g.weight} Prozent.${g.id==='23'?' Gemeinsam für Modul 2 und 3; nur der höhere gewichtete Wert zählt.':''} Im Entwurf unverändert.`;return true;}return false;
}
